import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.util.Set;
import java.util.TreeSet;

public class CF933C_V5 {
    public static final double EPSILON = 1e-10;
    static final boolean IS_REMOTE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;
    public static Scanner scanner;

    public static void main(String[] args) throws FileNotFoundException {
        if (!IS_REMOTE_JUDGE) {
            System.setIn(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF933C.in"));
        }
        scanner = new Scanner(System.in);
        mainLogic();
    }

    public static void mainLogic() {
        int n = scanner.nextInt();
        Circle[] circles = new Circle[n];

        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(scanner.nextInt(), scanner.nextInt(), scanner.nextInt());
        }

        if (n == 3 && !Circle.overlap(circles[0], circles[1])) {
            int count = 4;
            if (Circle.overlap2(circles[0], circles[2])) {
                count++;
            }
            if (Circle.overlap2(circles[1], circles[2])) {
                count++;
            }
            System.out.println(count);
            return;
        }

        int total = 1;
        TreeSet<Point> points = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            points.clear();
            total++;
            for (int j = 0; j < i; j++) {
                Circle.getIntersections(circles[i], circles[j], points);
            }
            if (points.size() >= 2) {
                total += points.size() - 1;
            }
        }

        System.out.println(total);
    }

    public static double distance(Point a, Point b) {
        return Math.sqrt(distanceSquared(a, b));
    }

    public static double distanceSquared(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    public static class Circle {
        Point center;
        int radius;

        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.radius = r;
        }

        public static boolean overlap(Circle a, Circle b) {
            double d = distance(a.center, b.center);
            return d <= a.radius + b.radius + EPSILON && d + EPSILON >= Math.abs(a.radius - b.radius);
        }

        public static boolean overlap2(Circle a, Circle b) {
            double d = distance(a.center, b.center);
            return d < a.radius + b.radius && d > Math.abs(a.radius - b.radius);
        }

        public static void getIntersections(Circle a, Circle b, Set<Point> set) {
            if (!overlap(a, b)) {
                return;
            }

            Line segment = new Line(a.center, b.center);
            double d = distance(a.center, b.center);
            double distToMid = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
            Point mid = a.center.translate(segment, distToMid);
            Point dir = segment.direction().perpendicular();
            double h = Math.sqrt(a.radius * a.radius - distToMid * distToMid);
            Point p1 = mid.translate(dir, h);
            Point p2 = mid.translate(dir, -h);

            set.add(p1);
            if (!p2.equals(p1)) {
                set.add(p2);
            }
        }
    }

    public static class Point implements Comparable<Point> {
        double x, y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public Point subtract(Point other) {
            return new Point(x - other.x, y - other.y);
        }

        public Point translate(Line line, double dist) {
            return translate(line.direction(), dist);
        }

        public Point translate(Point vector, double dist) {
            Point unit = vector.normalize();
            return add(unit.multiply(dist));
        }

        public Point add(Point other) {
            return new Point(x + other.x, y + other.y);
        }

        public Point multiply(double factor) {
            return new Point(x * factor, y * factor);
        }

        public Point normalize() {
            double mag = Math.sqrt(x * x + y * y);
            return divide(mag);
        }

        public Point divide(double divisor) {
            return new Point(x / divisor, y / divisor);
        }

        public Point perpendicular() {
            return new Point(-y, x);
        }

        @Override
        public boolean equals(Object obj) {
            Point other = (Point) obj;
            return Math.abs(x - other.x) < EPSILON && Math.abs(y - other.y) < EPSILON;
        }

        @Override
        public int compareTo(Point o) {
            if (equals(o)) {
                return 0;
            }
            if (Math.abs(x - o.x) < EPSILON) {
                return Double.compare(y, o.y);
            }
            return Double.compare(x, o.x);
        }
    }

    public static class Line {
        Point start;
        Point end;

        public Line(Point start, Point end) {
            this.start = start;
            this.end = end;
        }

        public Point direction() {
            return end.subtract(start);
        }

        public double length() {
            return distance(start, end);
        }
    }

    public static class Scanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0, len = 0;

        public Scanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            while (ptr >= len) {
                try {
                    len = stream.read(buffer);
                } catch (Exception e) {
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            int value = 0;
            while (c > 32) {
                value = value * 10 + (c - '0');
                c = read();
            }
            return negative ? -value : value;
        }

        public boolean hasNext() {
            int c = read();
            while (c <= 32) c = read();
            return c != -1;
        }
    }
}
